import @vibe/parser { parse_program_located, lex_with_offsets }
import @vibe/compiler/codegen/common_analysis {
  compute_borrow_param_user_fns, compute_borrow_disqualifiers, bmask_has
}
import @vibe/compiler/core { Stmt, Expr }

fn main allows Fs + Console + Exception {
  let source = Fs::read_file("_build/top-scope-refs/gen/cli_adapter_module_source.vibe")
  let (tokens, starts, _) = lex_with_offsets(source)
  let stmts = parse_program_located(tokens, starts, source)
  println("source bytes=\{String::length(source)} statements=\{Array::length(stmts)}")
  let masks: Array[Int] = []
  let names = compute_borrow_param_user_fns(stmts, [], masks)
  let valued: Array[String] = []
  let nonident_names: Array[String] = []
  let positions: Array[Int] = []
  compute_borrow_disqualifiers(stmts, valued, nonident_names, positions)
  let mut i = 0
  while i < Array::length(stmts) {
    match Array::get(stmts, i) {
      SLet(_, _, name, _, EFn(_, _, params, _, _, _)) => {
        if i < 5 { println("first fn=\{name}") }
        if String::starts_with(name, "rewrite_expr_") || String::starts_with(name, "mrv_fresh_") || String::starts_with(name, "collect_free_vars_expr_sc_") {
          let mut mask = 0
          let mut j = 0
          while j < Array::length(names) {
            if Array::get(names, j) == name { mask = Array::get(masks, j) }
            j = j + 1
          }
          println("\{name}: mask=\{mask}")
          j = 0
          while j < Array::length(params) {
            let (param, _) = Array::get(params, j)
            let mut nonident = false
            let mut k = 0
            while k < Array::length(nonident_names) {
              if Array::get(nonident_names, k) == name && Array::get(positions, k) == j { nonident = true }
              k = k + 1
            }
            println("  \{j} \{param}: borrowed=\{bmask_has(mask, j)} nonident=\{nonident}")
            j = j + 1
          }
        }
      },
      _ => ()
    }
    i = i + 1
  }
}
